#!/bin/bash
# Generate the paper's three datasets into data/.
#   scripts/generate_data.sh                 # all three
#   scripts/generate_data.sh karel list      # a subset (karel | list | rasp)
#   scripts/generate_data.sh karel+ list+ rasp+   # Finding 2's redundancy-injected copies (after their base sets)
#   WORKERS=32 scripts/generate_data.sh      # worker processes for Karel / List (default: all cores)
# Karel and List are generated by many worker processes and take hours (Karel: ~8-12 h on 64 cores). Each set has a
# fixed seed and a fixed train/test split (Karel / List: 100,000 / 2,500 programs; RASP: 32,000 / 2,500 samples).
# The injected copies rewrite half of each split's labels with extra structure that changes no trace (~20% of
# tokens), into data/<base>-rw50 (Karel, List) and data/<base>-nested-rw50 (RASP).
set -euo pipefail
cd "$(dirname "$0")/.."
WORKERS=${WORKERS:-$(nproc 2>/dev/null || sysctl -n hw.ncpu)}
SETS=${*:-karel list rasp}

for set in $SETS; do
    case "$set" in
    karel)
        python -m karel_env.generator_mp --dir_name=karel16x16-100k-d6-len-15-20-v2 \
            --num_workers="$WORKERS" --num_train=100000 --num_test=2500 --seed=2026 \
            --cover_all_branches_in_demos --canonicalize --dsl_version=2 \
            --height=16 --width=16 --min_demo_length=15 --max_demo_length=20 --max_program_len=100 \
            --num_demo_per_program=6 --max_demo_generation_trial=100 ;;
    list)
        python -m list_env.generator_mp --dir_name=list_l20v20-100k-d6-u100-len-15-20-v2 \
            --num_workers="$WORKERS" --num_train=100000 --num_test=2500 --seed=2026 \
            --cover_all_branches_in_demos --canonicalize --min_state_uniqueness=1.0 \
            --max_val=20 --L_max=20 --min_init_len=4 --max_program_stmt_depth=6 --max_program_nesting_depth=4 \
            --min_demo_length=15 --max_demo_length=20 --max_program_len=100 \
            --num_demo_per_program=6 --max_demo_generation_trial=200 ;;
    rasp)
        RASP_VOCAB_SIZE=18 RASP_MAX_SEQ_LEN=16 RASP_FAMILY=base python -m rasp_env.sweep_generator \
            --dir_name=rasp_v18s16-sweep32k --num_train_samples=32000 ;;
    karel+)
        python -m karel_env.rewrite --src=karel16x16-100k-d6-len-15-20-v2 --workers="$WORKERS" ;;
    list+)
        python -m karel_env.rewrite --src=list_l20v20-100k-d6-u100-len-15-20-v2 --workers="$WORKERS" ;;
    rasp+)
        RASP_VOCAB_SIZE=18 RASP_MAX_SEQ_LEN=16 RASP_FAMILY=nested python -m rasp_env.rewrite \
            --src=rasp_v18s16-sweep32k --rate=0.5 --seed=0 ;;
    *)
        echo "unknown dataset '$set' (karel | list | rasp | karel+ | list+ | rasp+)" >&2; exit 1 ;;
    esac
done
